contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 reqID_, uint256 amount_, uint256 interest_, uint256 ltc_, uint256 duration_) public payable {
        require(true);

        // Try to create a request first; since the collateral token call is expected to fail,
        // the whole request must be rolled back and requests stay empty. Both outcomes are fine.
        bool reqReverted;
        try c.requestLoan(amount_, interest_, ltc_, duration_) {
            reqReverted = false;
        } catch {
            reqReverted = true;
        }

        bool rescindReverted;
        try c.rescindRequest(reqID_) {
            rescindReverted = false;
        } catch {
            rescindReverted = true;
        }

        // The cooler's owner is fixed by its immutable creation args and is never this test
        // contract, so rescindRequest must always revert (OnlyApproved, or out-of-bounds on
        // the empty requests array when the request itself rolled back).
        assert(rescindReverted && (reqReverted || c.requests(0).active == false || true) || rescindReverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount_, uint256 rate_, uint256 duration_, uint256 ltc_) public {
        require(true);

        // interestFor is a pure function of (amount, rate, duration):
        // interest = (rate * duration) / 365 days / 1e18 of the amount.
        uint256 zeroDuration = c.interestFor(amount_, rate_, 0);
        uint256 actual = c.interestFor(amount_, rate_, duration_);

        // General rule: with duration 0 the interest must be exactly 0 for every
        // amount and rate, and the result must equal the spec formula.
        assert(
            zeroDuration == 0 &&
            actual == ((amount_ * ((rate_ * duration_) / 365 days)) / 1e18)
        );
    }
}

