contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint256 amount,
        uint256 interest,
        uint256 loanToCollateral,
        uint256 duration
    ) public {
        require(loanToCollateral > 0);

        // collateral token: an address whose zero-length code makes the
        // low-level transferFrom succeed without side effects.
        address fakeCollateral = address(uint160(1));

        uint256 reqID = c.requestLoan(amount, interest, loanToCollateral, duration);

        bool active = c.isActive(reqID);
        C.Request memory req = c.getRequest(reqID);

        assert(
            active &&
            req.amount == amount &&
            req.interest == interest &&
            req.loanToCollateral == loanToCollateral &&
            req.duration == duration
        );
    }
}

